type Job = { kind: 'resize'; path: string; width: number }
         | { kind: 'hash'; path: string };
type Result = { ok: true; value: string } | { ok: false; error: string };
const pool = Array.from({ length: 4 }, () => new Worker(new URL('./worker.ts', import.meta.url)));
let inflight = 0;                                   // bounded in-flight set
function submit(job: Job): Promise<Result> {
  const w = pool[inflight++ % pool.length];        // queueing layer
  return new Promise((resolve) => { w.once('message', resolve as (r: Result) => void);
                                    w.postMessage(job); });
}
